// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/config", wrapper.GetAuthConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/login", wrapper.LoginStart)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.LoginLocal)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/callback", wrapper.LoginCallback)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/currencies", wrapper.ListCurrencies)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households", wrapper.ListHouseholds)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/households", wrapper.CreateHousehold)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/households/{householdId}", wrapper.DeleteHousehold)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}", wrapper.GetHousehold)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/households/{householdId}", wrapper.UpdateHousehold)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}/members", wrapper.ListMembers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/households/{householdId}/members/{userId}", wrapper.RemoveMember)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/households/{householdId}/members/{userId}", wrapper.UpdateMember)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}/invitations", wrapper.ListInvitations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/households/{householdId}/invitations", wrapper.CreateInvitation)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/households/{householdId}/invitations/{invitationId}", wrapper.RevokeInvitation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/invitations/preview", wrapper.PreviewInvitation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/invitations/accept", wrapper.AcceptInvitation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/invitations/register", wrapper.RegisterWithInvitation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}/bots", wrapper.ListBots)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/households/{householdId}/bots", wrapper.CreateBot)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/households/{householdId}/bots/{botId}", wrapper.DeleteBot)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}/bots/{botId}", wrapper.GetBot)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/households/{householdId}/bots/{botId}", wrapper.UpdateBot)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/households/{householdId}/bots/{botId}/token", wrapper.RotateBotToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/households/{householdId}/audit", wrapper.ListAudit)

	return m
}

