// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LoginCallback Powrót od dostawcy OIDC
	// (GET /auth/callback)
	LoginCallback(ctx context.Context, request LoginCallbackRequestObject) (LoginCallbackResponseObject, error)
	// GetAuthConfig Co jest włączone na instancji (dla ekranu logowania)
	// (GET /auth/config)
	GetAuthConfig(ctx context.Context, request GetAuthConfigRequestObject) (GetAuthConfigResponseObject, error)
	// LoginStart Rozpoczyna logowanie OIDC (Authorization Code + PKCE)
	// (GET /auth/login)
	LoginStart(ctx context.Context, request LoginStartRequestObject) (LoginStartResponseObject, error)
	// LoginLocal Logowanie e-mailem i hasłem; ustawia cookie sesji
	// (POST /auth/login)
	LoginLocal(ctx context.Context, request LoginLocalRequestObject) (LoginLocalResponseObject, error)
	// Logout Kończy sesję; bez ważnej sesji też odpowiada 204
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListCurrencies Obsługiwane waluty ISO 4217 z liczbą miejsc dziesiętnych
	// (GET /currencies)
	ListCurrencies(ctx context.Context, request ListCurrenciesRequestObject) (ListCurrenciesResponseObject, error)
	// ListHouseholds Gospodarstwa wywołującego (bot — tylko własne)
	// (GET /households)
	ListHouseholds(ctx context.Context, request ListHouseholdsRequestObject) (ListHouseholdsResponseObject, error)
	// CreateHousehold Zakłada gospodarstwo; twórca zostaje ownerem
	// (POST /households)
	CreateHousehold(ctx context.Context, request CreateHouseholdRequestObject) (CreateHouseholdResponseObject, error)
	// DeleteHousehold Usuwa gospodarstwo z członkostwami, zaproszeniami, botami i audytem (owner)
	// (DELETE /households/{householdId})
	DeleteHousehold(ctx context.Context, request DeleteHouseholdRequestObject) (DeleteHouseholdResponseObject, error)

	// (GET /households/{householdId})
	GetHousehold(ctx context.Context, request GetHouseholdRequestObject) (GetHouseholdResponseObject, error)
	// UpdateHousehold Zmienia nazwę, strefę czasową lub dzień startu miesiąca (owner, admin)
	// (PATCH /households/{householdId})
	UpdateHousehold(ctx context.Context, request UpdateHouseholdRequestObject) (UpdateHouseholdResponseObject, error)
	// ListAudit Dziennik zmian od najnowszych (owner, admin)
	// (GET /households/{householdId}/audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// ListBots Boty — owner i admin widzą wszystkie, pozostali własne
	// (GET /households/{householdId}/bots)
	ListBots(ctx context.Context, request ListBotsRequestObject) (ListBotsResponseObject, error)
	// CreateBot Tworzy bota (owner, admin, member); token pokazywany raz
	// (POST /households/{householdId}/bots)
	CreateBot(ctx context.Context, request CreateBotRequestObject) (CreateBotResponseObject, error)
	// DeleteBot Usuwa bota; jego token przestaje działać
	// (DELETE /households/{householdId}/bots/{botId})
	DeleteBot(ctx context.Context, request DeleteBotRequestObject) (DeleteBotResponseObject, error)

	// (GET /households/{householdId}/bots/{botId})
	GetBot(ctx context.Context, request GetBotRequestObject) (GetBotResponseObject, error)
	// UpdateBot Zmienia nazwę, scope'y, portfele, wygaśnięcie lub wyłącza bota
	// (PATCH /households/{householdId}/bots/{botId})
	UpdateBot(ctx context.Context, request UpdateBotRequestObject) (UpdateBotResponseObject, error)
	// RotateBotToken Wymienia token bota; stary przestaje działać natychmiast
	// (POST /households/{householdId}/bots/{botId}/token)
	RotateBotToken(ctx context.Context, request RotateBotTokenRequestObject) (RotateBotTokenResponseObject, error)
	// ListInvitations Zaproszenia od najnowszego (owner, admin)
	// (GET /households/{householdId}/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// CreateInvitation Zaprasza e-mail z rolą; zwraca jednorazowy link (owner, admin)
	// (POST /households/{householdId}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// RevokeInvitation Odwołuje zaproszenie; ponowne odwołanie też daje 204
	// (DELETE /households/{householdId}/invitations/{invitationId})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)

	// (GET /households/{householdId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// RemoveMember Usuwa członka lub pozwala odejść samemu; wyłącza boty, których członek jest twórcą
	// (DELETE /households/{householdId}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMember Zmienia rolę członka
	// (PATCH /households/{householdId}/members/{userId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// AcceptInvitation Przyjęcie zaproszenia przez zalogowanego człowieka
	// (POST /invitations/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// PreviewInvitation Co kryje link zaproszenia (bez logowania)
	// (POST /invitations/preview)
	PreviewInvitation(ctx context.Context, request PreviewInvitationRequestObject) (PreviewInvitationResponseObject, error)
	// RegisterWithInvitation Zakłada konto lokalne na zaproszony e-mail, przyjmuje zaproszenie i loguje
	// (POST /invitations/register)
	RegisterWithInvitation(ctx context.Context, request RegisterWithInvitationRequestObject) (RegisterWithInvitationResponseObject, error)
	// GetMe Kim jest wywołujący — człowiek z gospodarstwami albo bot z uprawnieniami
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// LoginCallback operation middleware
func (sh *strictHandler) LoginCallback(w http.ResponseWriter, r *http.Request, params LoginCallbackParams) {
	var request LoginCallbackRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.LoginCallback(ctx, request.(LoginCallbackRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "LoginCallback")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginCallbackResponseObject); ok {
		if err := validResponse.VisitLoginCallbackResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

